#define PI 3.1415926535897932

int main(void)
{
    double r, h;
    double cl, cs, cvz;

    if (scanf("%lf %lf", &r, &h) != 2)
        return 1;

    cl = 2 * PI * r;
    cs = PI * r * r;
    cvz = cs * h;

    printf("cl=%.2f\n", cl);
    printf("cs=%.2f\n", cs);
    printf("cvz=%.2f\n", cvz);

    return 0;
}

